<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import {usePhasePage} from '../phasePage'
import {complianceError,leaveKind,type ContractPage,type LeaveAccounts,type LeaveKind} from '../complianceTypes'
import {storeToday} from '../time'
import BusinessSteps from '../components/BusinessSteps.vue'
import EmploymentContractForm from '../components/EmploymentContractForm.vue'
import LeaveBalanceLedger from '../components/LeaveBalanceLedger.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
const {api,home,base,english,loading,busy,failure,notice,load,write}=usePhasePage(),id=String(useRoute().params.employeeId)
const step=ref(0),page=ref<ContractPage|null>(null),accounts=ref<LeaveAccounts|null>(null),year=ref(Number(storeToday().slice(0,4))),openingOn=ref(storeToday()),contractId=ref(''),note=ref(''),reviewed=ref(false)
const openings=ref<Record<LeaveKind,number>>({annual:0,sick:0,hospital:0,company:0}),hasExtra=ref(false)
const task=ref<'review'|'adjust'|'year-end'>('review'),accountId=ref(''),available=ref(0),quantity=ref(0),expiresOn=ref(`${year.value}-12-31`)
const currentContracts=computed(()=>page.value?.items.filter(c=>!page.value?.companyId||c.companyId===page.value.companyId)||[])
const currentBalances=computed(()=>accounts.value?.balances.filter(b=>!page.value?.companyId||b.account.companyId===page.value.companyId)||[])
const selected=computed(()=>accounts.value?.balances.find(b=>b.account.id===accountId.value)),canManage=computed(()=>page.value?.canManage&&home.value?.myself?.id!==id)
function refresh(){void load(async()=>({p:await api().get<ContractPage>('/employees/'+id+'/employment-contracts'),a:await api().get<LeaveAccounts>(`/leave-accounts?employeeId=${id}&year=${year.value}`)}),v=>{page.value=v.p;accounts.value=v.a;contractId.value=v.p.items.filter(c=>!v.p.companyId||c.companyId===v.p.companyId).at(-1)?.id||'';accountId.value=currentBalances.value[0]?.account.id||'';available.value=currentBalances.value[0]?.available||0;if(!currentContracts.value.length)step.value=0;else if(!currentBalances.value.length)step.value=1})}
function saveContract(body:unknown){void write(()=>api().put('/employees/'+id+'/employment-contracts/'+crypto.randomUUID(),body),()=>{step.value=1;refresh()})}
function enable(){if(!reviewed.value||!contractId.value)return;const kinds:LeaveKind[]=hasExtra.value?['annual','sick','hospital','company']:['annual','sick','hospital'];void write(()=>api().put('/leave-accounts/enable/'+crypto.randomUUID(),{employeeId:id,year:year.value,contractId:contractId.value,openingOn:openingOn.value,openings:kinds.map(kind=>({kind,remaining:openings.value[kind]})),note:note.value}),()=>{step.value=2;refresh()})}
function apply(){if(!note.value.trim())return;const a=selected.value?.account;const body=task.value==='year-end'?{employeeId:id,year:year.value,note:note.value}:task.value==='adjust'?{employeeId:id,accountId:a?.id,expectedVersion:a?.version,quantity:quantity.value,expiresOn:expiresOn.value,note:note.value}:{employeeId:id,accountId:a?.id,expectedVersion:a?.version,contractId:contractId.value,reviewOn:openingOn.value,available:available.value,note:note.value};void write(()=>api().put('/leave-accounts/'+task.value+'/'+crypto.randomUUID(),body),()=>{if(task.value==='year-end'){year.value++;openingOn.value=`${year.value}-01-01`}step.value=2;refresh()})}
onMounted(refresh)
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{page?.employeeName}} · {{english()?'Contract & leave':'合同与假期'}}</h2><RouterLink :to="base+'/employees/'+id+'/edit'">{{english()?'Employee details':'员工资料'}}</RouterLink></header><p class="wf-hint">{{english()?'Confirm the contract, reconcile the opening balance, then use the existing leave approvals. No historical wages are recalculated.':'先确认合同，再对账启用额度；之后沿用请假申请和审批。历史工资不会重新计算。'}}</p><PhaseStatus :loading="loading" :busy="busy" :failure="failure" :notice="notice"/><BusinessSteps v-model="step" :disabled="busy" :steps="english()?['Contract','Enable balance','Balance & leave','Review / year-end']:['确认合同','对账启用','余额与请假','复核／年结']"/><template v-if="page&&!loading"><div v-show="step===0"><EmploymentContractForm v-if="canManage" :key="page.items.length" :page="page" :english="english()" :busy="busy" @save="saveContract"/><p v-else-if="!page.items.length">{{english()?'Your manager has not adopted a contract policy yet.':'尚未采用合同政策，请联系管理员核对。'}}</p><details v-if="page.items.length" class="wf-section"><summary>{{english()?'Contract version history':'已确认合同版本'}}</summary><article v-for="c in [...page.items].reverse()" :key="c.id" class="wf-history"><strong>v{{c.version}} · {{c.effectiveFrom}} · {{c.partTime?(english()?'Part-time':'兼职'):(english()?'Full-time':'全职')}}</strong><p>{{c.dailyHours}} {{english()?'hours/day':'小时／天'}} · {{c.weeklyHours}} {{english()?'hours/week':'小时／周'}} · {{c.weeklyDays}} {{english()?'days/week':'天／周'}}</p><p>{{page.policies.find(p=>p.id===c.policyId&&p.version===c.policyVersion)?.name}} · v{{c.policyVersion}}</p><p>{{c.evidence}}</p></article></details></div><div v-show="step===1"><p v-if="currentBalances.length" class="wf-hint">{{english()?'This year is already enabled. Use balance review for changes.':'本年度已启用；变更请使用「复核／年结」，不会重复发放期初额度。'}}</p><form v-else-if="canManage&&currentContracts.length" @submit.prevent="enable"><fieldset :disabled="busy"><h3>{{english()?'Enter reconciled remaining balances':'填写已对账的剩余额度'}}</h3><p class="wf-hint">{{english()?'Include leave already taken through the cutoff. Pending and future approved requests must be reconciled before activation.':'先扣除截至对账日已使用额度。待批及未来已批请假须先核对，系统不会重复扣减旧记录。零表示已核对确无余额。'}}</p><div class="wf-grid"><label>{{english()?'Year':'额度年度'}}<input v-model.number="year" type="number" min="2000" max="2100" required></label><label>{{english()?'Reconciled through':'对账截止日'}}<input v-model="openingOn" type="date" required></label><label>{{english()?'Contract':'采用合同'}}<select v-model="contractId" required><option v-for="c in page.items.filter(c=>!page?.companyId||c.companyId===page.companyId)" :key="c.id" :value="c.id">v{{c.version}} · {{c.effectiveFrom}} · {{c.partTime?(english()?'hours':'小时'):(english()?'days':'天')}}</option></select></label><label v-for="kind in (hasExtra?['annual','sick','hospital','company']:['annual','sick','hospital']) as LeaveKind[]" :key="kind">{{leaveKind(kind,english())}}<input v-model.number="openings[kind]" type="number" min="0" step="0.000001" required></label></div><label class="wf-check"><input v-model="hasExtra" type="checkbox">{{english()?'Separate additional company leave':'另设企业额外假账户'}}</label><label>{{english()?'Reconciliation evidence':'期初对账依据'}}<textarea v-model="note" required maxlength="1000" rows="3"/></label><label class="wf-check"><input v-model="reviewed" type="checkbox" required>{{english()?'All balances and existing requests have been reconciled.':'已核对全部余额和已有申请。'}}</label><footer class="wf-form-actions"><button class="primary" :disabled="!reviewed">{{english()?'Enable reconciled balances':'确认并启用额度'}}</button></footer></fieldset></form><p v-else>{{english()?'Confirm a contract first.':'请先确认合同。'}}</p></div><div v-show="step===2"><form class="wf-inline" @submit.prevent="refresh"><label>{{english()?'Year':'查看年度'}}<input v-model.number="year" type="number" min="2000" max="2100"></label><button :disabled="busy">{{english()?'View':'查看'}}</button></form><p v-for="code in [...new Set(accounts?.balances.flatMap(b=>b.issues)||[])]" :key="code" class="wf-error">{{complianceError(code,english())||code}}</p><LeaveBalanceLedger :balances="currentBalances" :companies="home?.companies||[]" :english="english()"/><footer class="wf-form-actions"><RouterLink class="wf-button primary" :to="base+'/leaves'">{{english()?'Next: leave applications & approval':'下一步：请假与审批'}}</RouterLink><RouterLink :to="base+'/approvals'">{{english()?'Approve hours':'核准工时'}}</RouterLink></footer></div><div v-show="step===3"><form v-if="canManage&&currentBalances.length" @submit.prevent="apply"><fieldset :disabled="busy"><label>{{english()?'Task':'办理事项'}}<select v-model="task"><option value="review">{{english()?'Review changed contract / unpaid accrual':'复核合同变化／无薪假影响'}}</option><option value="adjust">{{english()?'Record explained adjustment':'记录有依据的额度调整'}}</option><option value="year-end">{{english()?'Close year and carry forward':'年结及结转新年度'}}</option></select></label><p class="wf-hint">{{task==='year-end'?(english()?'Run after 1 January. Preserve unexpired annual leave and reservations; sick leave starts anew.':'1月1日后办理，保留依法结转年假与在途占用；病假新年度重新发放。年假不会在12月31日自动清零。'):(english()?'Every adjustment adds an audit movement. Existing leave and payroll history remains intact.':'调整会追加流水，保留原申请和已确认工资。仅在核对依据后填写。')}}</p><div v-if="task!=='year-end'" class="wf-grid"><label>{{english()?'Account':'假期账户'}}<select v-model="accountId" @change="available=selected?.available||0"><option v-for="b in currentBalances" :key="b.account.id" :value="b.account.id">{{leaveKind(b.account.kind,english())}} · {{b.account.unit==='day'?(english()?'days':'天'):(english()?'hours':'小时')}}</option></select></label><template v-if="task==='review'"><label>{{english()?'Reviewed available balance':'核对后的可用余额'}}<input v-model.number="available" type="number" min="0" step="0.000001" required></label><label>{{english()?'Review date':'复核截止日'}}<input v-model="openingOn" type="date" required></label><label>{{english()?'Contract version':'采用合同'}}<select v-model="contractId"><option v-for="c in page.items.filter(c=>!page?.companyId||c.companyId===page.companyId)" :key="c.id" :value="c.id">v{{c.version}} · {{c.effectiveFrom}}</option></select></label></template><template v-else><label>{{english()?'Adjustment (+/-)':'调整数量（正数增加，负数扣减）'}}<input v-model.number="quantity" type="number" step="0.000001" required></label><label>{{english()?'Expiry':'到期日'}}<input v-model="expiresOn" type="date" required></label></template></div><label>{{english()?'Evidence and explanation':'依据与说明'}}<textarea v-model="note" required rows="3" maxlength="1000"/></label><footer class="wf-form-actions"><button class="primary">{{english()?'Confirm this task':'确认本项办理'}}</button></footer></fieldset></form><p v-else>{{english()?'No account available for management.':'尚无可管理的额度账户。'}}</p></div></template></section></template>
